ri-unified-notifications');?></label><label><?php esc_html_e('History retention view (days)','sabri-unified-notifications');?><input type="number" min="7" max="365" name="history_days" value="<?php echo esc_attr($attention_profile['history_days']??90);?>"></label><label><?php esc_html_e('Temporary mute until','sabri-unified-notifications');?><input type="datetime-local" name="muted_until"></label><button class="sun-button" type="submit"><?php esc_html_e('Save attention settings','sabri-unified-notifications');?></button></form></section>
